function model(p) {
  // Newton's cannon: a body launched from 300 km above an Earth-like planet at a chosen speed and angle. Gravity is
  // the only force. The closed-form orbit (energy, semi-major axis, eccentricity, period) says whether it circles,
  // loops, crashes or escapes; the trajectory itself is integrated with RK4 so the picture and the formula can be compared.
  const speed = Math.max(5, Math.min(12, Math.round(p.speed * 4) / 4));
  const angle = Math.max(0, Math.min(45, Math.round(p.angle)));
  const massFactor = Math.max(0.5, Math.min(2, Math.round(p.planetMass * 4) / 4));
  const R = 6371, h0 = 300, mu = 398600 * massFactor; // km, km, km^3/s^2
  const r0 = R + h0, a0 = angle * Math.PI / 180;
  const vCirc = Math.sqrt(mu / r0), vEsc = Math.sqrt(2 * mu / r0);
  const energy = speed * speed / 2 - mu / r0; // specific orbital energy, km^2/s^2
  const hAng = r0 * speed * Math.cos(a0); // specific angular momentum
  const escapes = energy >= 0;
  const a = escapes ? null : -mu / (2 * energy);
  const e = Math.sqrt(Math.max(0, 1 + 2 * energy * hAng * hAng / (mu * mu)));
  const rp = hAng * hAng / mu / (1 + e), ra = escapes ? null : hAng * hAng / mu / (1 - e);
  // Direction of periapsis from the eccentricity vector at launch (r = (r0, 0), v = (v sin a, v cos a))
  const vx0 = speed * Math.sin(a0), vy0 = speed * Math.cos(a0), rv = r0 * vx0, v2 = speed * speed;
  const ex = ((v2 - mu / r0) * r0 - rv * vx0) / mu, ey = (0 - rv * vy0) / mu, periapsisAngle = e > 1e-6 ? Math.atan2(ey, ex) : 0;
  const period = escapes ? null : 2 * Math.PI * Math.sqrt(a * a * a / mu);
  const crashes = rp < R - 1e-6; // the low point of the path is below the surface, whatever the energy
  const outcome = crashes ? 'crash' : escapes ? 'escape' : e < 0.02 ? 'circular' : 'ellipse';
  // Integrate: position (x, y) km, velocity km/s; launch at (r0, 0) heading +y, tilted outward by the angle
  let x = r0, y = 0, vx = speed * Math.sin(a0), vy = speed * Math.cos(a0), t = 0;
  const acc = (px, py) => { const d = Math.hypot(px, py), f = -mu / (d * d * d); return [f * px, f * py]; };
  const span = escapes ? 4 * 3600 : Math.min(2 * period, 8 * 3600), N = 720, dtSample = span / N, sub = 20, dt = dtSample / sub;
  const path = [{ t: 0, x, y, r: r0, v: speed }];
  let impact = null, energyDrift = 0, minR = r0, maxR = r0;
  for (let i = 1; i <= N && !impact; i++) {
    for (let k = 0; k < sub; k++) {
      const [ax1, ay1] = acc(x, y);
      const x2 = x + vx * dt / 2, y2 = y + vy * dt / 2, vx2 = vx + ax1 * dt / 2, vy2 = vy + ay1 * dt / 2, [ax2, ay2] = acc(x2, y2);
      const x3 = x + vx2 * dt / 2, y3 = y + vy2 * dt / 2, vx3 = vx + ax2 * dt / 2, vy3 = vy + ay2 * dt / 2, [ax3, ay3] = acc(x3, y3);
      const x4 = x + vx3 * dt, y4 = y + vy3 * dt, vx4 = vx + ax3 * dt, vy4 = vy + ay3 * dt, [ax4, ay4] = acc(x4, y4);
      x += dt / 6 * (vx + 2 * vx2 + 2 * vx3 + vx4); y += dt / 6 * (vy + 2 * vy2 + 2 * vy3 + vy4);
      vx += dt / 6 * (ax1 + 2 * ax2 + 2 * ax3 + ax4); vy += dt / 6 * (ay1 + 2 * ay2 + 2 * ay3 + ay4); t += dt;
      const r = Math.hypot(x, y);
      if (r <= R) { impact = { t, x: x / r * R, y: y / r * R }; break; }
    }
    const r = Math.hypot(x, y), v = Math.hypot(vx, vy);
    minR = Math.min(minR, r); maxR = Math.max(maxR, r);
    energyDrift = Math.max(energyDrift, Math.abs((v * v / 2 - mu / r) - energy) / Math.abs(energy || 1));
    path.push(impact ? { t: impact.t, x: impact.x, y: impact.y, r: R, v } : { t, x, y, r, v });
  }
  const simSpan = path[path.length - 1].t, duration = 24;
  path.forEach(s => { s.at = +(s.t / simSpan * duration).toFixed(3); Object.keys(s).forEach(k => { s[k] = +(+s[k]).toFixed(k === 'at' ? 3 : 2); }); });
  // Periapsis passes in the integrated path (local minima of r) give a measured period to compare with Kepler
  const passes = path[1] && path[1].r >= path[0].r ? [0] : []; // a horizontal launch above circular speed starts at periapsis
  for (let i = 1; i < path.length - 1; i++) if (path[i].r < path[i - 1].r && path[i].r <= path[i + 1].r && path[i].r < r0 + 1) passes.push(path[i].t);
  const measuredPeriod = passes.length >= 2 ? passes[1] - passes[0] : null;
  const fmtKm = v => Math.round(v).toLocaleString('en-US') + ' km';
  const fmtH = s => s >= 3600 ? (s / 3600).toFixed(2) + ' h' : Math.round(s / 60) + ' min';
  const verdict = outcome === 'escape' ? 'Escapes: faster than ' + vEsc.toFixed(2) + ' km/s, it never comes back.' : outcome === 'crash' ? 'Crashes after ' + fmtH(impact ? impact.t : 0) + ': the low point of the orbit is below the surface.' : outcome === 'circular' ? 'A circle at ' + fmtKm(h0) + ' altitude, once every ' + fmtH(period) + '.' : 'An ellipse: altitude from ' + fmtKm(rp - R) + ' to ' + fmtKm(ra - R) + ', once every ' + fmtH(period) + '.';
  const steps = [
    { id: 'launch', t: 0, title: 'Launch at ' + speed.toFixed(2) + ' km/s', note: 'From 300 km up, ' + (angle ? angle + '° above horizontal' : 'horizontally') + '. Circular speed here is ' + vCirc.toFixed(2) + ' km/s, escape speed ' + vEsc.toFixed(2) + ' km/s' + (massFactor !== 1 ? ' for a planet of ' + massFactor + ' × Earth\'s mass' : '') + '.' },
    { id: 'shape', t: 6, title: outcome === 'escape' ? 'Energy ≥ 0: an open path' : 'Energy < 0: a closed orbit', note: 'Specific energy ' + energy.toFixed(1) + ' km²/s². ' + (escapes ? 'Gravity slows it but never stops it.' : 'Semi-major axis ' + fmtKm(a) + ', eccentricity ' + e.toFixed(2) + ': the shape is fixed at launch.') },
    { id: 'verdict', t: 14, title: verdict.split(':')[0], note: verdict },
    { id: 'sowhat', t: 20, title: 'So what', note: 'Speed, not height, decides. Below circular speed the orbit dips into the planet; between circular and escape speed it is an ellipse whose far side rises with every extra m/s.' }
  ];
  const summary = speed.toFixed(2) + ' km/s at ' + angle + '°' + (massFactor !== 1 ? ', ' + massFactor + ' × Earth' : '') + ': ' + verdict + (measuredPeriod && period ? ' Measured period ' + fmtH(measuredPeriod) + ' vs Kepler ' + fmtH(period) + '.' : '');
  return { R, h0, mu, massFactor, speed, angle, vCirc: +vCirc.toFixed(3), vEsc: +vEsc.toFixed(3), energy: +energy.toFixed(3), a: a && +a.toFixed(1), e: +e.toFixed(4), rp: +rp.toFixed(1), ra: ra && +ra.toFixed(1), period: period && +period.toFixed(1), measuredPeriod: measuredPeriod && +measuredPeriod.toFixed(1),
    escapes, crashes, outcome, impact, path, periapsisAngle: +periapsisAngle.toFixed(5), minR: +minR.toFixed(1), maxR: +maxR.toFixed(1), energyDrift: +energyDrift.toFixed(5), simSpan: +simSpan.toFixed(1), verdict, steps, duration, markers: steps.map(s => s.t), summary };
}

