function check(p) {
  const m = model(p), last = m.path[m.path.length - 1];
  // Energy is conserved along the integrated path, and the path's low and high points match the closed-form orbit
  const energyOk = m.energyDrift < 0.005;
  const lowOk = m.crashes ? m.minR <= m.R + 1 : Math.abs(m.minR - m.rp) / m.rp < 0.01;
  const highOk = m.escapes || m.crashes ? true : Math.abs(m.maxR - m.ra) / m.ra < 0.01;
  // Outcome follows the energy sign and the periapsis; the path ends on the surface exactly when it crashes
  const signOk = m.escapes === (m.energy >= 0) && m.crashes === (m.rp < m.R - 1e-6);
  const endOk = m.crashes ? (!!m.impact && Math.abs(last.r - m.R) < 1) : (!m.impact && last.r > m.R);
  // Kepler's third law: the time between periapsis passes equals the closed-form period when two passes fit the window
  const keplerOk = m.measuredPeriod === null || Math.abs(m.measuredPeriod - m.period) / m.period < 0.02;
  const speedsOk = Math.abs(m.vEsc / m.vCirc - Math.SQRT2) < 1e-3 && m.escapes === (m.speed >= m.vEsc - 1e-3);
  const pass = energyOk && lowOk && highOk && signOk && endOk && keplerOk && speedsOk;
  return {
    pass,
    detail: 'Outcome ' + m.outcome + ' (energy ' + m.energy.toFixed(1) + ', periapsis ' + Math.round(m.rp) + ' km vs radius ' + m.R + ' km)' + (signOk ? '' : ' (inconsistent)') + '; energy drift ' + (100 * m.energyDrift).toFixed(3) + ' %' + (energyOk ? '' : ' (too much)') +
      '; integrated low/high ' + Math.round(m.minR) + '/' + Math.round(m.maxR) + ' km against closed-form ' + Math.round(m.rp) + '/' + (m.ra ? Math.round(m.ra) : '∞') + ' km' + (lowOk && highOk ? '' : ' (mismatch)') +
      (m.measuredPeriod ? '; measured period ' + (m.measuredPeriod / 60).toFixed(1) + ' min vs Kepler ' + (m.period / 60).toFixed(1) + ' min' + (keplerOk ? '.' : ' (mismatch).') : '.')
  };
}
